import { throttle, debounce } from 'throttle-debounce'
import { mapState, mapGetters } from 'vuex'
import { RENJU } from '@/store/modules/settings'
import { paddingTop, paddingBottom, paddingX, fillCircle, drawBackground, drawCoord, drawBoard, drawPiece } from '@/components/boardDraw'

function hexToRgba(sHex, alpha = 1) {
  // 十六进制颜色值的正则表达式
  let reg = /^#([0-9a-fA-f]{3}|[0-9a-fA-f]{6})$/
  /* 16进制颜色转为RGB格式 */
  let sColor = sHex.toLowerCase()
  if (sColor && reg.test(sColor)) {
    if (sColor.length === 4) {
      let sColorNew = '#'
      for (let i = 1; i < 4; i += 1) {
        sColorNew += sColor.slice(i, i + 1).concat(sColor.slice(i, i + 1))
      }
      sColor = sColorNew
    }
    // 处理六位的颜色值
    let sColorChange = []
    for (let i = 1; i < 7; i += 2) {
      sColorChange.push(parseInt('0x' + sColor.slice(i, i + 2)))
    }
    // return sColorChange.join(',')
    // 或
    return 'rgba(' + sColorChange.join(',') + ',' + alpha + ')'
  } else {
    return sColor
  }
}

function drawIndex(ctx, style, cs, position, end, startIndex, highlight) {
  ctx.save()
  ctx.font = style.indexFontStyle + ' ' + style.indexScale * cs + 'px ' + style.indexFontFamily
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.translate(paddingX + cs / 2, paddingTop + cs / 2)

  end = Math.min(end, position.length)
  for (let i = startIndex; i < end - 1; i += 1) {
    let pos = position[i]
    let text = i - startIndex + 1
    ctx.fillStyle = i % 2 == 0 ? style.indexColorBlack : style.indexColorWhite
    ctx.fillText(text, cs * pos[0], cs * pos[1], cs)
  }

  if (end > startIndex) {
    let pos = position[end - 1]
    if (highlight) ctx.fillStyle = style.lastStepColor
    else ctx.fillStyle = end % 2 == 1 ? style.indexColorBlack : style.indexColorWhite
    ctx.fillText(end - startIndex, cs * pos[0], cs * pos[1], cs)
  }

  ctx.restore()
}

function drawLastStep(ctx, style, cs, position, end, startIndex) {
  end = Math.min(end, position.length)
  if (end <= startIndex) return
  ctx.save()
  ctx.fillStyle = style.lastStepColor
  ctx.translate(paddingX + cs / 2, paddingTop + cs / 2)
  ctx.scale(cs, cs)
  let pos = position[end - 1]
  fillCircle(ctx, pos[0], pos[1], style.lastStepScale)
  ctx.restore()
}

function drawRealtime(ctx, style, cs, moves) {
  ctx.save()
  ctx.translate(paddingX + cs / 2, paddingTop + cs / 2)
  ctx.scale(cs, cs)

  ctx.fillStyle = style.lostMoveColor
  for (let p of moves.lost) {
    fillCircle(ctx, p[0], p[1], style.realtimeMoveScale)
  }

  ctx.fillStyle = style.bestMoveColor
  for (let p of moves.best) {
    fillCircle(ctx, p[0], p[1], style.bestMoveScale)
  }

  ctx.restore()
}

function drawPvEval(ctx, showType, style, cs, pv) {
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'

  let halfcs = cs / 2
  let bgColor = hexToRgba(style.boardColor, style.pvEvalAlpha)
  ctx.translate(paddingX + halfcs, paddingTop + halfcs)

  for (let i = pv.length - 1; i >= 0; i -= 1) {
    if (pv[i].bestline && pv[i].bestline.length > 0) {
      let pos = pv[i].bestline[0]
      let x = cs * pos[0]
      let y = cs * pos[1]
      ctx.fillStyle = bgColor
      ctx.fillRect(x - halfcs, y - halfcs, cs, cs)
      ctx.fillStyle = i > 0 ? style.thoughtMoveColor : style.bestMoveColor

      ctx.font =
        style.pvEvalFontStyle + ' ' + style.pvEvalScale * cs + 'px ' + style.pvEvalFontFamily
      if (showType == 1) {
        ctx.fillText(pv[i].eval, x, y, cs * 0.95)
      } else if (showType == 2) {
        if (pv[i].winrate == 0.0 || pv[i].winrate == 1.0) ctx.fillText(pv[i].eval, x, y, cs * 0.95)
        else ctx.fillText((pv[i].winrate * 100).toFixed(1), x, y, cs * 0.95)
      } else {
        ctx.fillText(pv[i].eval, x, y - cs * 0.2, cs * 0.95)
        ctx.font =
          (style.pvEvalFontStyle * 2) / 3 +
          ' ' +
          style.pvEvalScale * cs * 0.8 +
          'px ' +
          style.pvEvalFontFamily
        ctx.fillText(pv[i].depth + '-' + pv[i].seldepth, x, y + cs * 0.2, cs * 0.95)
      }
    }
  }
}

function drawKillPointScores(ctx, style, cs, scores) {
  if (!scores || scores.length === 0) return

  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'

  let halfcs = cs / 2
  ctx.translate(paddingX + halfcs, paddingTop + halfcs)

  for (let i = 0; i < scores.length; i++) {
    const score = scores[i]
    if (!score.eval || (score.evalType !== 'win' && score.evalType !== 'loss')) continue

    let x = cs * score.x
    let y = cs * score.y

    // 背景
    let bgColor = hexToRgba('#FF6D00', 0.15)
    ctx.fillStyle = bgColor
    ctx.fillRect(x - halfcs, y - halfcs, cs, cs)

    // 文字颜色
    if (score.evalType === 'win') {
      ctx.fillStyle = '#FF0000' // 必胜红色
    } else if (score.evalType === 'loss') {
      ctx.fillStyle = '#0000FF' // 必败蓝色
    } else {
      // 普通评分：正分偏红，负分偏蓝
      const val = parseInt(score.eval) || 0
      if (val > 0) {
        ctx.fillStyle = '#FF4500' // 正分红色
      } else if (val < 0) {
        ctx.fillStyle = '#1E90FF' // 负分蓝色
      } else {
        ctx.fillStyle = '#888' // 0分灰色
      }
    }

    // 绘制评分
    ctx.font = 'bold ' + cs * 0.35 + 'px sans-serif'
    ctx.fillText(score.eval, x, y, cs * 0.95)
  }
}

function drawHeatmap(ctx, style, cs, points, maxPoints) {
  if (!points || points.length === 0) return
  const visible = points
    .filter((point) => point && Number.isFinite(Number(point[0])) && Number.isFinite(Number(point[1])))
    .slice()
    .sort((a, b) => {
      const ar = Number(a[4]) || 0
      const br = Number(b[4]) || 0
      return ar && br ? ar - br : ar ? -1 : br ? 1 : (Number(b[3]) || 0) - (Number(a[3]) || 0)
    })
    .slice(0, Math.max(1, Number(maxPoints) || 10))

  ctx.save()
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.translate(paddingX + cs / 2, paddingTop + cs / 2)
  for (let i = 0; i < visible.length; i += 1) {
    const point = visible[i]
    const x = Number(point[0])
    const y = Number(point[1])
    const winrate = Math.max(0, Math.min(1, Number(point[2]) || 0))
    const visits = Math.max(0, Number(point[3]) || 0)
    const rank = Number(point[4]) || i + 1
    const best = rank === 1
    const radius = cs * 0.42

    ctx.beginPath()
    ctx.arc(x * cs, y * cs, radius, 0, Math.PI * 2)
    ctx.fillStyle = best ? '#35b9d5' : '#90ed0b'
    ctx.globalAlpha = best ? 0.96 : 0.88
    ctx.fill()
    ctx.globalAlpha = 1

    ctx.fillStyle = best ? '#064b67' : '#17300d'
    ctx.font = 'bold ' + Math.max(9, cs * 0.18) + 'px sans-serif'
    ctx.fillText((winrate * 100).toFixed(1) + '%', x * cs, y * cs - cs * 0.06, cs * 0.95)
    ctx.font = 'bold ' + Math.max(8, cs * 0.15) + 'px sans-serif'
    const visitText = visits >= 10000 ? (visits / 1000).toFixed(0) + 'K' : visits >= 1000 ? (visits / 1000).toFixed(1) + 'K' : String(Math.round(visits))
    ctx.fillText(visitText, x * cs, y * cs + cs * 0.18, cs * 0.95)

    ctx.beginPath()
    ctx.arc(x * cs - cs * 0.31, y * cs - cs * 0.31, cs * 0.16, 0, Math.PI * 2)
    ctx.fillStyle = best ? '#075673' : '#18202a'
    ctx.fill()
    ctx.fillStyle = '#fff'
    ctx.font = 'bold ' + Math.max(8, cs * 0.16) + 'px sans-serif'
    ctx.fillText(String(rank), x * cs - cs * 0.31, y * cs - cs * 0.31, cs * 0.95)
  }
  ctx.restore()
}

function drawSelection(ctx, style, cs, pos) {
  ctx.save()
  ctx.strokeStyle = style.selectionStrokeColor
  ctx.lineWidth = style.selectionStrokeWidth
  ctx.translate(paddingX + cs / 2, paddingTop + cs / 2)
  ctx.scale(cs, cs)

  ctx.beginPath()
  ctx.moveTo(pos[0] - 0.5, pos[1] - 0.5)
  ctx.lineTo(pos[0] + 0.5, pos[1] - 0.5)
  ctx.lineTo(pos[0] + 0.5, pos[1] + 0.5)
  ctx.lineTo(pos[0] - 0.5, pos[1] + 0.5)
  ctx.closePath()
  ctx.stroke()

  ctx.restore()
}

function drawForbid(ctx, style, cs, forbid) {
  ctx.save()
  ctx.strokeStyle = style.forbidStrokeColor
  ctx.lineWidth = style.forbidStrokeWidth
  ctx.lineCap = 'round'
  ctx.translate(paddingX + cs / 2, paddingTop + cs / 2)
  ctx.scale(cs, cs)

  const CrossSize = 0.22

  for (let pos of forbid) {
    ctx.beginPath()
    ctx.moveTo(pos[0] - CrossSize, pos[1] - CrossSize)
    ctx.lineTo(pos[0] + CrossSize, pos[1] + CrossSize)
    ctx.stroke()
    ctx.beginPath()
    ctx.moveTo(pos[0] + CrossSize, pos[1] - CrossSize)
    ctx.lineTo(pos[0] - CrossSize, pos[1] + CrossSize)
    ctx.stroke()
  }

  ctx.restore()
}

export default {
  name: 'Board',
  props: {
    isAiTurn: Boolean,
    previewPv: Object,
    killPointScores: Array,
  },
  data: function () {
    return {
      debouncedRedrawAllLayers: debounce(50, this.redrawAllLayers),
      throttledDrawRealtimeLayer: throttle(10, this.drawRealtimeLayer),
      selecting: false,
      selectedCoord: [0, 0],
      pressed: false,
      cancelMouse: false,
    }
  },
  computed: {
    ...mapState('position', {
      boardSize: 'size',
      position: 'position',
      setupCount: 'setupCount',
      winline: 'winline',
    }),
    ...mapState('settings', [
      'boardStyle',
      'showCoord',
      'showPvEval',
      'showIndex',
      'showForbid',
      'showKillPoints',
      'showHeatmap',
      'kataGoMaxPoints',
      'engineType',
      'clickCheck',
    ]),
    ...mapState('ai', {
      realtime: (state) => state.outputs.realtime,
      pv: (state) => state.outputs.pv,
      forbid: (state) => state.outputs.forbid,
      thinking: 'thinking',
    }),
    heatmap() {
      const analyzedPosition = this.$store.state.ai.lastThinkPosition
      if (analyzedPosition.length !== this.position.length || analyzedPosition.some((move, index) =>
        move[0] !== this.position[index][0] || move[1] !== this.position[index][1]
      )) return []
      return this.$store.state.ai.outputs.heatmap
    },
    ...mapGetters('position', ['isInBoard', 'playerToMove']),
    ...mapGetters('settings', ['gameRule']),
    context() {
      return (idx) => {
        return this.$refs['canvas' + idx].getContext('2d')
      }
    },
    canvasWidth() {
      return this.$store.getters.boardCanvasWidth
    },
    canvasHeight() {
      return this.canvasWidth - 2 * paddingX + paddingBottom + paddingTop
    },
    boardWidth() {
      return this.canvasWidth - 2 * paddingX
    },
    canvasStyle() {
      return {
        width: this.canvasWidth + 'px',
        height: this.canvasHeight + 'px',
      }
    },
    renderRatio() {
      // 屏幕的设备像素比(解决高DPI屏模糊问题)
      return window.devicePixelRatio || 1
    },
    renderWidth() {
      return this.canvasWidth * this.renderRatio
    },
    renderHeight() {
      return this.canvasHeight * this.renderRatio
    },
  },
  methods: {
    drawBoardLayer(ctx, noclear) {
      ctx = ctx || this.context('Board')
      let width = this.canvasWidth
      let height = this.canvasHeight
      let cellSize = this.boardWidth / this.boardSize

      ctx.save()
      ctx.scale(this.renderRatio, this.renderRatio)
      if (!noclear) ctx.clearRect(0, 0, width, height)

      drawBackground(ctx, this.boardStyle, width, height, noclear)
      if (this.showCoord) drawCoord(ctx, this.boardStyle, width, height, this.boardSize, cellSize)
      drawBoard(ctx, this.boardStyle, this.boardSize, cellSize)

      ctx.restore()
    },
    drawPieceLayer(ctx, noclear) {
      ctx = ctx || this.context('Piece')
      let cellSize = this.boardWidth / this.boardSize
      ctx.save()
      ctx.scale(this.renderRatio, this.renderRatio)
      if (!noclear) ctx.clearRect(0, 0, this.canvasWidth, this.canvasHeight)

      if (this.previewPv) {
        let previewPosition = this.previewPv.position.concat(this.previewPv.pv)
        drawPiece(ctx, this.boardStyle, cellSize, previewPosition, Infinity)
        drawIndex(
          ctx,
          this.boardStyle,
          cellSize,
          previewPosition,
          Infinity,
          this.previewPv.position.length,
          true
        )
      } else {
        drawPiece(ctx, this.boardStyle, cellSize, this.position, Infinity)
        if (this.showIndex)
          drawIndex(ctx, this.boardStyle, cellSize, this.position, Infinity, this.setupCount, true)
        else drawLastStep(ctx, this.boardStyle, cellSize, this.position, Infinity, this.setupCount)
      }

      ctx.restore()
    },
    drawRealtimeLayer(ctx, noclear) {
      ctx = ctx || this.context('Realtime')
      let cellSize = this.boardWidth / this.boardSize
      ctx.save()
      ctx.scale(this.renderRatio, this.renderRatio)
      if (!noclear) ctx.clearRect(0, 0, this.canvasWidth, this.canvasHeight)

      if (this.engineType === 'RAPFI' && this.gameRule === RENJU && this.playerToMove === 'BLACK' &&
        this.showForbid && !this.thinking && !this.previewPv) {
        drawForbid(ctx, this.boardStyle, cellSize, this.forbid)
      }

      if (this.engineType === 'KATAGO' && this.showHeatmap && !this.previewPv) {
        drawHeatmap(ctx, this.boardStyle, cellSize, this.heatmap, this.kataGoMaxPoints)
      }

      if (this.selecting) drawSelection(ctx, this.boardStyle, cellSize, this.selectedCoord)
      else if (!this.previewPv) {
        drawRealtime(ctx, this.boardStyle, cellSize, this.realtime)
        if (this.engineType === 'RAPFI' && this.showPvEval > 0 && this.pv.length > 0 && this.thinking)
          drawPvEval(ctx, this.showPvEval, this.boardStyle, cellSize, this.pv)
      }

      if (
        this.engineType === 'RAPFI' &&
        this.showKillPoints &&
        !this.thinking &&
        !this.previewPv &&
        this.killPointScores &&
        this.killPointScores.length > 0
      ) {
        drawKillPointScores(ctx, this.boardStyle, cellSize, this.killPointScores)
      }

      ctx.restore()
    },
    redrawAllLayers(ctx, noclear) {
      this.drawBoardLayer(ctx, noclear)
      this.drawPieceLayer(ctx, noclear)
      this.drawRealtimeLayer(ctx, noclear)
    },
    onMouseDown(event) {
      if (this.clickCheck == 2) {
        if (event.type === 'touchstart') {
          this.cancelMouse = true
          event.button = 0
          if (!event.pageX) event.pageX = event.touches[0].pageX
          if (!event.pageY) event.pageY = event.touches[0].pageY
        } else if (this.cancelMouse) {
          this.cancelMouse = false
          return
        }
      }

      let x = event.pageX - this.$refs.canvasBoard.getBoundingClientRect().left
      let y = event.pageY - this.$refs.canvasBoard.getBoundingClientRect().top
      let cellSize = this.boardWidth / this.boardSize
      x = Math.floor((x - paddingX) / cellSize)
      y = Math.floor((y - paddingTop) / cellSize)

      if (event.button != 0) {
        this.$emit('clicked', { x, y, button: event.button })
        return
      } else if (this.winline.length > 0) return

      if (this.clickCheck == 0 || this.isAiTurn)
        this.$emit('clicked', { x, y, button: event.button })
      else if (this.clickCheck == 1) {
        if (this.selecting) {
          let dx = Math.abs(x - this.selectedCoord[0])
          let dy = Math.abs(y - this.selectedCoord[1])
          if (Math.max(dx, dy) <= 1)
            this.$emit('clicked', {
              x: this.selectedCoord[0],
              y: this.selectedCoord[1],
              button: event.button,
            })
        } else {
          this.selectedCoord = [x, y]
        }
        this.selecting = !this.selecting
      } else if (this.clickCheck == 2) {
        this.pressed = true
        this.selectedCoord = [x, y - 2]
        this.selecting = this.isInBoard(this.selectedCoord)
      }
    },
    onMouseUp(event) {
      if (!this.pressed) return

      if (event.type === 'touchend') {
        event.preventDefault()
        event.button = 0
      }

      this.$emit('clicked', {
        x: this.selectedCoord[0],
        y: this.selectedCoord[1],
        button: event.button,
      })

      this.selecting = false
      this.pressed = false
    },
    onMouseMove(event) {
      if (!this.pressed) return

      if (event.type === 'touchmove') {
        event.preventDefault()
        event.button = 0
        if (!event.pageX) event.pageX = event.touches[0].pageX
        if (!event.pageY) event.pageY = event.touches[0].pageY
      }

      let x = event.pageX - this.$refs.canvasBoard.getBoundingClientRect().left
      let y = event.pageY - this.$refs.canvasBoard.getBoundingClientRect().top
      let cellSize = this.boardWidth / this.boardSize
      x = Math.floor((x - paddingX) / cellSize)
      y = Math.floor((y - paddingTop) / cellSize)

      let oldCoord = this.selectedCoord
      this.selectedCoord = [x, y - 2]
      this.selecting = this.isInBoard(this.selectedCoord)

      if (
        this.selecting &&
        (oldCoord[0] != this.selectedCoord[0] || oldCoord[1] != this.selectedCoord[1])
      ) {
        this.throttledDrawRealtimeLayer()
      }
    },
  },
  watch: {
    '$store.state.screenWidth': function () {
      this.debouncedRedrawAllLayers()
    },
    '$store.state.screenHeight': function () {
      this.debouncedRedrawAllLayers()
    },
    canvasWidth() {
      this.debouncedRedrawAllLayers()
    },
    boardSize() {
      this.debouncedRedrawAllLayers()
    },
    position: {
      handler() {
        this.drawPieceLayer()
        this.drawRealtimeLayer()
      },
      deep: true,
    },
    realtime: {
      handler() {
        this.throttledDrawRealtimeLayer()
      },
      deep: true,
    },
    pv: {
      handler() {
        if (this.showPvEval > 0) this.throttledDrawRealtimeLayer()
      },
      deep: true,
    },
    forbid() {
      if (this.showForbid) this.drawRealtimeLayer()
    },
    heatmap: {
      handler() {
        if (this.engineType === 'KATAGO' && this.showHeatmap) this.throttledDrawRealtimeLayer()
      },
      deep: true,
    },
    previewPv() {
      this.drawPieceLayer()
      this.drawRealtimeLayer()
    },
    killPointScores() {
      this.drawRealtimeLayer()
    },
    thinking() {
      this.drawRealtimeLayer()
    },
    showCoord() {
      this.drawBoardLayer()
    },
    showPvEval() {
      this.drawRealtimeLayer()
    },
    showIndex() {
      this.drawPieceLayer()
    },
    showForbid() {
      this.drawRealtimeLayer()
    },
    showKillPoints() {
      this.drawRealtimeLayer()
    },
    showHeatmap() {
      this.drawRealtimeLayer()
    },
    kataGoMaxPoints() {
      this.drawRealtimeLayer()
    },
    engineType() {
      this.drawRealtimeLayer()
    },
    selecting() {
      this.throttledDrawRealtimeLayer()
    },
    boardStyle: {
      handler() {
        this.debouncedRedrawAllLayers()
      },
      deep: true,
    },
  },
  mounted() {
    this.redrawAllLayers()
    window.addEventListener('mousemove', throttle(50, this.onMouseMove))
    window.addEventListener('mouseup', this.onMouseUp)
    window.addEventListener('touchmove', throttle(50, this.onMouseMove), {
      passive: false,
    })
    window.addEventListener('touchend', this.onMouseUp, { passive: false })
  },
}
